page_styles.fullscreen:
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #ffffff;
}
canvas {
  display: block;
}

page_styles.preview:
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  overflow: hidden;
  background: #dce8f4;
  cursor: pointer;
}
canvas {
  display: block;
  cursor: auto;
}

page_styles.live:
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  overflow: hidden;
  background: #dce8f4;
}
canvas {
  display: block;
}
